import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
def transform(g):
    h,w=len(g),len(g[0]); out=[r[:] for r in g]
    # for each non-background, non-fill color, find bounding box; fill interior zeros
    cols=set(x for r in g for x in r)
    bg=8
    for c in cols-{bg,7}:
        cells=[(i,j) for i in range(h) for j in range(w) if g[i][j]==c]
        if not cells: continue
        r0=min(i for i,j in cells); r1=max(i for i,j in cells)
        c0=min(j for i,j in cells); c1=max(j for i,j in cells)
        if r1-r0>=2 and c1-c0>=2:
            for i in range(r0+1,r1):
                for j in range(c0+1,c1):
                    if g[i][j]==bg: out[i][j]=7
    return out
print(transform(G['Demo pair 1 input'])==G['Demo pair 1 output'])
o=transform(G['Test input'])
for r in o: print(' '.join(map(str,r)))
print(json.dumps(o))
